{
  "findings": [
    {
      "check_id": "CKV_AZURE_109",
      "title": "Key Vault Key size is less than 2048 bits for RSA",
      "resource": "azurerm_key_vault_key.generated",
      "severity": "MEDIUM",
      "explanation": "The RSA key size is set to 2048, which is the minimum acceptable value but often considered weak for long-term security or high-compliance environments. Modern best practices recommend using at least 3072 or 4096 bits for RSA keys to ensure sufficient cryptographic strength against future attacks."
    }
  ],
  "patched_code": "resource "azurerm_key_vault_key" "generated" {
  name         = "terragoat-generated-certificate-${var.environment}"
  key_vault_id = azurerm_key_vault.example.id
  key_type     = "RSA"
  key_size     = 3072
  key_opts = [
    "decrypt",
    "encrypt",
    "sign",
    "unwrapKey",
    "verify",
    "wrapKey",
  ]
}",
  "fix_summary": "Increased the RSA key size from 2048 to 3072 bits to align with stronger cryptographic standards and improve resistance to brute-force attacks."
}
